arguments.command:
node -e '
const fs = require("fs");
const lines = fs.readFileSync("/reference/glossary.jsonl", "utf8").trim().split("\n");
const cats = new Set();
for (const line of lines) {
  const d = JSON.parse(line);
  if (d.kind === "value") cats.add(d.category);
}
console.log(Array.from(cats).sort());
'

node -e '
const fs = require("fs");
const needs = JSON.parse(fs.readFileSync("/needs.json", "utf8"));
for (const n of needs) {
  console.log(n.id, n.kind, n.source, n.text);
}
'

node -e '
const fs = require("fs");
const data = JSON.parse(fs.readFileSync("/needs.json", "utf8"));
const needs = data.needs || data;
for (const [k, v] of Object.entries(needs)) {
  console.log(v.id || k, v.kind, v.source, v.text || v.meaning);
}
'
